/**
 *
 * SliderHandle is a component that displays a handle.
 *
 * [Live Demo](https://www.primereact.org/slider/)
 *
 * @module SliderHandle
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type * as React from 'react';
import type { SliderRootInstance } from './SliderRoot.types';
/**
 * Defines passthrough(pt) options type in SliderHandle component.
 */
export type SliderHandlePassThroughType<E> = PassThroughType<SliderHandleInstance, E>;
/**
 * Defines passthrough(pt) options of SliderHandle component.
 */
export interface SliderHandlePassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SliderHandlePassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SliderHandle component.
 */
export interface SliderHandleProps extends BaseComponentProps<SliderHandleInstance, unknown, SliderHandlePassThrough> {
    /**
     * Index of the handle.
     * @default 0
     */
    index?: number | undefined;
    /**
     * Index of the element in tabbing order.
     * @default 0
     */
    tabIndex?: number | undefined;
    /**
     * Establishes a string value that labels the component.
     */
    ariaLabel?: string | undefined;
    /**
     * Establishes relationships between the component and label(s) where its value should be one or more element IDs.
     */
    ariaLabelledby?: string | undefined;
    /**
     * Name attribute of the input.
     */
    name?: string | undefined;
    /**
     * Id of the input.
     */
    inputId?: string | undefined;
    /**
     * Style of the input element.
     */
    inputStyle?: React.CSSProperties | undefined;
    /**
     * Style class of the input element.
     */
    inputClassName?: string | undefined;
    /**
     * When present, it specifies that the element should be disabled.
     * @default false
     */
    disabled?: boolean | undefined;
    /**
     * When present, it specifies that the element should be read-only.
     * @default false
     */
    readOnly?: boolean | undefined;
    /**
     * When present, it specifies that the element is invalid.
     * @default false
     */
    invalid?: boolean | undefined;
    /**
     * When present, it specifies that the element is required.
     */
    required?: boolean | undefined;
    /**
     * Callback fired on focus.
     */
    onFocus?: React.FocusEventHandler<HTMLInputElement> | undefined;
    /**
     * Callback fired on blur.
     */
    onBlur?: React.FocusEventHandler<HTMLInputElement> | undefined;
}
/**
 * Defines valid state in SliderHandle component.
 */
export interface SliderHandleState {
}
/**
 * Extra props applied to the hidden input element inside the handle.
 */
export interface SliderHandleInputExtraProps {
    /**
     * Id of the input element.
     */
    id: string | undefined;
    /**
     * Style of the input element (visually hidden).
     */
    style: React.CSSProperties;
    /**
     * Class name of the input element.
     */
    className: string | undefined;
    /**
     * Name of the input element.
     */
    name: string | undefined;
    /**
     * Tab index for the input element.
     */
    tabIndex: number;
    /**
     * Whether the input is disabled.
     */
    disabled: boolean;
    /**
     * Whether the input is read-only.
     */
    readOnly: boolean;
    /**
     * ARIA labelledby for the input.
     */
    'aria-labelledby': string | undefined;
    /**
     * ARIA label for the input.
     */
    'aria-label': string | undefined;
    /**
     * Focus handler for the input element.
     */
    onFocus: React.FocusEventHandler<HTMLInputElement>;
    /**
     * Blur handler for the input element.
     */
    onBlur: React.FocusEventHandler<HTMLInputElement>;
}
/**
 * Defines the methods and properties exposed by SliderHandle component.
 */
export interface SliderHandleExposes {
    /**
     * The Slider component instance.
     */
    slider: SliderRootInstance | undefined | null;
    /**
     * Index of the handle within the slider.
     */
    handleIndex: number;
    /**
     * Extra props applied to the hidden input element.
     */
    extraInputProps: SliderHandleInputExtraProps;
}
/**
 * Instance of SliderHandle component.
 */
export type SliderHandleInstance = ComponentInstance<SliderHandleProps, SliderHandleState, SliderHandleExposes>;
